<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Aim, Connection, MagicStick, Medal, Warning } from '@element-plus/icons-vue'
import api,{errorText,unwrap} from '../api'
import { useAuthStore } from '../store'

const auth=useAuthStore();const data=ref({skills:[],gaps:[],heatmap:[],safetyCases:[],reviews:[],levelNames:[]});const selectedUserId=ref(null);const path=ref([]);const pathLoading=ref(false);const assessOpen=ref(false);const activeSkill=ref(null)
const assessment=reactive({level:3,comment:''});const review=reactive({week:new Date().toISOString().slice(0,10),achievements:'',blockers:'',supportNeeded:'',nextFocus:'',mentorComment:''})
const readinessClass=computed(()=>data.value.readiness>=80?'ready':data.value.readiness>=60?'growing':'risk')
async function load(){const params=selectedUserId.value?{userId:selectedUserId.value}:{};data.value=unwrap(await api.get('/capabilities',{params}));if(!selectedUserId.value&&auth.user?.role==='mentor'&&data.value.heatmap?.length){selectedUserId.value=data.value.heatmap[0].user.id;await load()}}
async function generatePath(){pathLoading.value=true;try{path.value=unwrap(await api.post('/training-path/generate',{userId:selectedUserId.value||auth.user.id})).path;ElMessage.success('已按能力差距生成培养路径')}catch(e){ElMessage.error(errorText(e))}finally{pathLoading.value=false}}
function openAssess(skill){activeSkill.value=skill;Object.assign(assessment,{level:skill.level,comment:skill.assessment?.comment||''});assessOpen.value=true}
async function saveAssessment(){try{await api.post(`/capabilities/${selectedUserId.value}/assess`,{skillId:activeSkill.value.id,...assessment});ElMessage.success('能力认证已保存');assessOpen.value=false;await load()}catch(e){ElMessage.error(errorText(e))}}
async function saveReview(){try{await api.post('/weekly-reviews',{...review,userId:selectedUserId.value||auth.user.id});ElMessage.success(auth.user?.role==='mentor'?'周复盘点评已保存':'周复盘已提交');await load()}catch(e){ElMessage.error(errorText(e))}}
onMounted(load)
</script>

<template><div class="page capability-page"><div class="page-title"><div><p class="eyebrow">JOB READINESS</p><h1>岗位胜任力与培养中心</h1><p>用真实任务和有效证据回答“是否具备独立上岗能力”</p></div><el-select v-if="auth.user?.role==='mentor'" v-model="selectedUserId" style="width:180px" @change="load"><el-option v-for="item in data.heatmap" :key="item.user.id" :label="`${item.user.name} · ${item.readiness}%`" :value="item.user.id"/></el-select></div>
<section class="capability-hero"><div class="readiness-ring" :class="readinessClass"><b>{{data.readiness||0}}%</b><span>岗位准备度</span></div><div><p>当前培养对象</p><h2>{{data.user?.name}} · {{data.user?.position}}</h2><div class="capability-summary"><span><b>{{data.skills.length}}</b>项岗位技能</span><span><b>{{data.gaps.length}}</b>项待提升</span><span><b>{{data.skills.reduce((s,i)=>s+i.evidenceCount,0)}}</b>份能力证据</span></div></div><div class="hero-principle"><el-icon><Connection/></el-icon><div><b>任务不是终点，胜任才是</b><span>安全前置 · 任务牵引 · 证据认证 · 逐级放权</span></div></div></section>
<div v-if="auth.user?.role==='mentor'" class="talent-heatmap panel"><div class="panel-head"><div><h2>班组人才技能热力图</h2><p>快速识别关键技能断层和培养优先级</p></div></div><div class="heatmap-table"><div class="heat-head">学员</div><div v-for="skill in data.skills" :key="skill.id" class="heat-head">{{skill.name}}</div><template v-for="person in data.heatmap" :key="person.user.id"><div class="heat-user"><b>{{person.user.name}}</b><span>{{person.readiness}}%</span></div><div v-for="skill in person.skills" :key="skill.id" class="heat-cell" :class="`level-${skill.level}`" :title="`${skill.name}：${skill.levelName}`">L{{skill.level}}<small>/{{skill.targetLevel}}</small></div></template></div></div>
<section class="panel skill-panel"><div class="panel-head"><div><h2>岗位能力地图</h2><p>五级成熟度：未接触、观察学习、协助完成、独立完成、能够带教</p></div><el-button type="primary" :icon="MagicStick" :loading="pathLoading" @click="generatePath">生成个性化培养路径</el-button></div><div class="skill-list"><article v-for="skill in data.skills" :key="skill.id" :class="{critical:skill.critical}"><div class="skill-domain"><el-icon><Warning v-if="skill.critical"/><Aim v-else/></el-icon><span>{{skill.domain}}</span></div><div class="skill-main"><div><b>{{skill.name}}</b><el-tag v-if="skill.critical" type="danger" size="small" effect="plain">关键技能</el-tag></div><p>{{skill.description}}</p><div class="level-track"><i v-for="level in 5" :key="level" :class="{done:level<=skill.level,target:level===skill.targetLevel}"></i></div><small>当前 {{skill.levelName}}（L{{skill.level}}） · 岗位目标 L{{skill.targetLevel}}</small></div><div class="skill-proof"><b>{{skill.evidenceCount}}</b><span>能力证据</span><small>{{skill.relatedTaskCount}} 个关联任务</small></div><el-button v-if="auth.user?.role==='mentor'" text type="primary" @click="openAssess(skill)">能力认证</el-button></article></div></section>
<section v-if="path.length" class="panel training-path"><div class="panel-head"><div><h2>AI 个性化培养路径</h2><p>按关键程度和能力差距排序，可直接转化为培养任务</p></div></div><div class="path-line"><article v-for="item in path" :key="item.stage"><span>{{item.stage}}</span><div><b>{{item.skillName}}</b><h3>{{item.objective}}</h3><p>{{item.action}}</p><div><el-tag v-for="evidence in item.evidence" :key="evidence" size="small" effect="plain">{{evidence}}</el-tag></div><small>建议周期：{{item.durationWeeks}}周</small></div></article></div></section>
<div class="capability-lower"><section class="panel safety-cases"><div class="panel-head"><div><h2>安全经验推荐</h2><p>根据能力缺口自动匹配师傅经验和典型风险</p></div></div><article v-for="item in data.safetyCases" :key="item.id"><div class="case-no">案例 {{item.id}}</div><h3>{{item.title}}</h3><p><b>作业场景：</b>{{item.scene}}</p><p class="case-risk"><b>核心风险：</b>{{item.risk}}</p><ul><li v-for="control in item.controls" :key="control">{{control}}</li></ul><blockquote>{{item.lesson}}</blockquote></article><el-empty v-if="!data.safetyCases.length" description="当前能力缺口暂无匹配案例"/></section>
<section class="panel weekly-review"><div class="panel-head"><div><h2>师徒周复盘</h2><p>复盘成果、阻碍与支持需求，形成下一周培养输入</p></div></div><template v-if="auth.user?.role==='apprentice'"><el-date-picker v-model="review.week" value-format="YYYY-MM-DD" style="width:100%"/><el-input v-model="review.achievements" type="textarea" :rows="2" placeholder="本周取得的可核验成果"/><el-input v-model="review.blockers" type="textarea" :rows="2" placeholder="遇到的困难和阻碍"/><el-input v-model="review.supportNeeded" type="textarea" :rows="2" placeholder="希望师傅提供的支持"/><el-input v-model="review.nextFocus" type="textarea" :rows="2" placeholder="下周重点"/><el-button type="primary" @click="saveReview">提交本周复盘</el-button></template><template v-else><el-alert v-if="data.reviews[0]" :title="`${data.user?.name}：${data.reviews[0].achievements}`" type="success" :closable="false" show-icon/><el-input v-model="review.mentorComment" type="textarea" :rows="4" placeholder="填写师傅点评和下周带教安排"/><el-button type="primary" @click="saveReview">保存点评</el-button></template><div class="review-history"><article v-for="item in data.reviews" :key="item.id"><b>{{item.week}}</b><el-tag :type="item.status==='reviewed'?'success':'warning'" size="small">{{item.status==='reviewed'?'已点评':'待点评'}}</el-tag><p>{{item.achievements}}</p><small>下周重点：{{item.nextFocus}}</small><blockquote v-if="item.mentorComment">师傅：{{item.mentorComment}}</blockquote></article></div></section></div>
<el-dialog v-model="assessOpen" title="五级能力认证" width="620"><template v-if="activeSkill"><el-alert :title="`${activeSkill.name} · 当前${activeSkill.levelName}`" type="info" :closable="false"/><el-form label-position="top"><el-form-item label="认证等级"><el-radio-group v-model="assessment.level"><el-radio-button v-for="(name,index) in data.levelNames" :key="name" :value="index+1">L{{index+1}} {{name}}</el-radio-button></el-radio-group></el-form-item><el-form-item label="有效证据（系统自动统计）"><div class="auto-evidence"><b>{{activeSkill.evidenceCount}} 项已核销工作</b><span>只统计已完成并经师傅核销、且关联该技能的任务，不能手工修改。</span><article v-for="item in activeSkill.evidenceSources||[]" :key="item.taskId"><strong>{{item.title}}</strong><small>{{item.completedAt}} · {{item.items.join('、')}}</small></article><el-empty v-if="!activeSkill.evidenceSources?.length" description="暂无已核销的关联工作" :image-size="42"/></div></el-form-item><el-form-item label="认证意见"><el-input v-model="assessment.comment" type="textarea" :rows="4" placeholder="说明学员可以独立完成的范围和仍需监护的场景"/></el-form-item></el-form></template><template #footer><el-button @click="assessOpen=false">取消</el-button><el-button type="primary" :icon="Medal" @click="saveAssessment">确认认证</el-button></template></el-dialog></div></template>

<style>
.capability-page{--cap-green:#087f42;--cap-orange:#d96500}.capability-hero{display:grid;grid-template-columns:130px 1fr minmax(320px,.8fr);gap:24px;align-items:center;background:#083a7c;color:#fff;padding:25px 30px;margin-bottom:18px;border-radius:7px}.readiness-ring{width:106px;height:106px;border:9px solid #ffffff26;border-top-color:#45d483;border-radius:50%;display:grid;place-content:center;text-align:center}.readiness-ring.growing{border-top-color:#ffb34b}.readiness-ring.risk{border-top-color:#ff7777}.readiness-ring b,.readiness-ring span{display:block}.readiness-ring b{font-size:25px}.readiness-ring span{font-size:9px;color:#c4d6ee}.capability-hero p,.capability-hero h2{margin:0 0 7px}.capability-summary{display:flex;gap:24px}.capability-summary span{font-size:10px;color:#bfd2ec}.capability-summary b{font-size:18px;color:#fff;margin-right:4px}.hero-principle{display:grid;grid-template-columns:42px 1fr;gap:12px;align-items:center;border-left:1px solid #ffffff30;padding-left:24px}.hero-principle>.el-icon{font-size:31px;color:#60dda0}.hero-principle b,.hero-principle span{display:block}.hero-principle span{font-size:10px;color:#bfd2ec;margin-top:5px}.talent-heatmap{margin-bottom:18px}.heatmap-table{display:grid;grid-template-columns:110px repeat(6,minmax(85px,1fr));overflow:auto;border:1px solid var(--line)}.heat-head,.heat-user,.heat-cell{min-height:53px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);display:grid;place-content:center;text-align:center;padding:6px}.heat-head{background:#f4f7fb;font-size:9px;font-weight:700}.heat-user b,.heat-user span{display:block}.heat-user span{font-size:9px;color:var(--muted)}.heat-cell{font-weight:800;color:#fff}.heat-cell small{font-size:8px;margin-left:2px}.level-1{background:#a8b0bc}.level-2{background:#6690c7}.level-3{background:#2972bd}.level-4{background:#16885a}.level-5{background:#086c43}.skill-panel{margin-bottom:18px}.skill-list article{display:grid;grid-template-columns:105px 1fr 90px 85px;gap:16px;align-items:center;padding:14px 0;border-top:1px solid #edf0f4}.skill-list article.critical{border-left:3px solid #e06d23;padding-left:12px}.skill-domain{display:flex;align-items:center;gap:7px;color:#58708f;font-size:10px}.skill-main>div{display:flex;align-items:center;gap:8px}.skill-main p{font-size:10px;color:var(--muted);margin:5px 0 8px}.level-track{display:grid;grid-template-columns:repeat(5,1fr);gap:5px}.level-track i{height:7px;background:#e3e8ef;border-radius:2px}.level-track i.done{background:#178756}.level-track i.target{outline:2px solid #f4a340;outline-offset:1px}.skill-main small,.skill-proof span,.skill-proof small{display:block;font-size:9px;color:var(--muted);margin-top:5px}.skill-proof{text-align:center}.skill-proof b{font-size:24px;color:var(--blue)}.training-path{margin-bottom:18px}.path-line{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.path-line article{position:relative;border:1px solid var(--line);border-top:3px solid var(--blue);padding:17px}.path-line article>span{position:absolute;right:10px;top:9px;font-size:25px;color:#dce5f2;font-weight:800}.path-line h3{font-size:12px;margin:8px 0}.path-line p{font-size:10px;color:var(--muted);line-height:1.7}.path-line .el-tag{margin:3px 4px 3px 0}.path-line small{display:block;color:#b15900;margin-top:8px}.capability-lower{display:grid;grid-template-columns:1.05fr .95fr;gap:18px}.safety-cases>article{border-top:1px solid #edf0f4;padding:15px 0}.case-no{font-size:9px;color:#a45b16}.safety-cases h3{font-size:14px;margin:5px 0 9px}.safety-cases p,.safety-cases li{font-size:10px;color:#59677b;line-height:1.7}.case-risk{background:#fff5eb;padding:8px;border-left:3px solid var(--cap-orange)}.safety-cases blockquote,.review-history blockquote{margin:8px 0;background:#edf6f1;border-left:3px solid var(--cap-green);padding:9px;font-size:10px;color:#35604b}.weekly-review>.el-input,.weekly-review>.el-date-editor,.weekly-review>.el-alert{margin-bottom:10px}.weekly-review>.el-button{width:100%}.review-history{margin-top:15px}.review-history article{border-top:1px solid #edf0f4;padding:12px 0}.review-history article>.el-tag{float:right}.review-history p{font-size:11px}.review-history small{color:var(--muted)}.task-skill-tags{display:flex;align-items:center;gap:5px;margin-top:6px}.task-skill-tags .risk-count{color:#b75c00;background:#fff2e3;padding:3px 6px;border-radius:3px;font-size:8px}.task-risk-box,.task-evidence{background:#fff8ee;border-left:3px solid #e6751d;padding:12px;margin-top:12px}.task-risk-box b,.task-risk-box label,.task-evidence b{display:block}.task-risk-box label{font-size:11px;margin-top:8px}.task-evidence .el-tag{margin:8px 6px 0 0}@media(max-width:1100px){.capability-hero{grid-template-columns:110px 1fr}.hero-principle{grid-column:1/-1;border-left:0;border-top:1px solid #ffffff30;padding:14px 0 0}.path-line{grid-template-columns:1fr 1fr}.capability-lower{grid-template-columns:1fr}.skill-list article{grid-template-columns:90px 1fr 70px}.skill-list article>.el-button{grid-column:2}}@media(max-width:700px){.capability-hero{grid-template-columns:1fr;text-align:center}.readiness-ring{margin:auto}.capability-summary{justify-content:center}.skill-list article{grid-template-columns:1fr}.skill-list article>.el-button{grid-column:1}.path-line{grid-template-columns:1fr}.heatmap-table{grid-template-columns:90px repeat(6,80px)}}
.auto-evidence{width:100%;background:#f4f8f7;border:1px solid #dce7e3;padding:12px}.auto-evidence>b,.auto-evidence>span{display:block}.auto-evidence>b{color:#087c66;font-size:15px}.auto-evidence>span{font-size:10px;color:#718092;margin:4px 0 10px}.auto-evidence article{background:#fff;border-top:1px solid #e2e8e6;padding:9px}.auto-evidence article strong,.auto-evidence article small{display:block}.auto-evidence article small{font-size:9px;color:#7c8997;margin-top:4px}
</style>

